import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.yFlg5W3A.js";const p=JSON.parse('{"title":"Say It Out Loud: Spoken Interview Scripts","description":"","frontmatter":{},"headers":[],"relativePath":"14-say-it-out-loud.md","filePath":"14-say-it-out-loud.md"}'),n={name:"14-say-it-out-loud.md"};function r(s,e,l,c,u,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="say-it-out-loud-spoken-interview-scripts" tabindex="-1">Say It Out Loud: Spoken Interview Scripts <a class="header-anchor" href="#say-it-out-loud-spoken-interview-scripts" aria-label="Permalink to &quot;Say It Out Loud: Spoken Interview Scripts&quot;">​</a></h1><h2 id="project-pitch-60-seconds" tabindex="-1">Project Pitch (60 Seconds) <a class="header-anchor" href="#project-pitch-60-seconds" aria-label="Permalink to &quot;Project Pitch (60 Seconds)&quot;">​</a></h2><blockquote><p>&quot;I built AstroCare, an autonomous clinical telemetry and decision-support platform for deep-space Mars missions where communication delays with Earth reach 24 minutes. Built with TypeScript, Express 5, MongoDB Time-Series, and Redis Streams, it ingests multi-lead biometric streams, filters sensor artifacts with a Signal Quality Analyzer, fuses alerts to eliminate alarm fatigue, and uses a machine learning sidecar to predict clinical decompensation 30 minutes in advance, while modeling interplanetary communication delays for Earth ground control.&quot;</p></blockquote><h2 id="feature-scripts" tabindex="-1">Feature Scripts <a class="header-anchor" href="#feature-scripts" aria-label="Permalink to &quot;Feature Scripts&quot;">​</a></h2><h3 id="f1-telemetry-ingestion-signal-quality" tabindex="-1">F1: Telemetry Ingestion &amp; Signal Quality <a class="header-anchor" href="#f1-telemetry-ingestion-signal-quality" aria-label="Permalink to &quot;F1: Telemetry Ingestion &amp; Signal Quality&quot;">​</a></h3><blockquote><p>&quot;I built the Telemetry Ingestion and Signal Quality Analyzer to handle noisy biometric streams in microgravity. In <code>ingestService.ts</code>, incoming sensor payloads are verified with constant-time HMAC tokens and an atomic 60-second idempotency lease to prevent duplicate submissions. In <code>qualityService.ts</code>, the readings pass through physiological plausibility checks, spike filters that reject single-point sensor noise, and flatline detection before entering MongoDB.&quot;</p></blockquote><h3 id="f2-interplanetary-delay-emulator" tabindex="-1">F2: Interplanetary Delay Emulator <a class="header-anchor" href="#f2-interplanetary-delay-emulator" aria-label="Permalink to &quot;F2: Interplanetary Delay Emulator&quot;">​</a></h3><blockquote><p>&quot;To replicate real mission physics, I engineered the Comms Delay Emulator in <code>linkEmulator.ts</code>. For ISS missions, latency is zero; for Lunar Artemis missions, it adds 1.3 seconds; and for Mars, it dynamically models 3 to 22 minutes of light-time delay based on planetary orbital alignment, buffering data in persistent outbox queues during planetary blackouts.&quot;</p></blockquote>',8)])])}const h=t(n,[["render",r]]);export{p as __pageData,h as default};
